style.css:
@-moz-document domain("roblox.com") {
/* ? Remove rounded corporate panels */
  .rounded-container, .modern-ui, .new-layout, .autoplay-video {
    display: none !important;
  }

  /* ? Restore classic layout vibes */
  .game-card, .legacy-ui, .classic-panel {
    display: block !important;
    border-radius: 0px !important;
    background-color: #1a1a1a !important;
    color: #fefefe !important;
    font-family: 'Arial Black', sans-serif !important;
  }

  /* ? Ritualize the background */
  body {
    background: linear-gradient(45deg, #0f0f0f, #1a1a1a) !important;
    color: #ffffff !important;
  }

  /* ? Hide sterile elements */
  .promotional-banner, .trending-carousel, .video-preview, .rounded-button {
    display: none !important;
  }

  /* ? Add glitch border to game thumbnails */
  .game-thumbnail {
    border: 2px dashed #ff00ff !important;
    filter: hue-rotate(45deg) contrast(120%) !important;
  }

  /* ? Optional: Replace fonts with cursed glyphs */
  h1, h2, h3, .game-title {
    font-family: 'Wingdings', 'Webdings', monospace !important;
  }
}
